package com.dating.backend.service;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import com.dating.backend.entity.User;import com.dating.backend.repository.UserRepository;import com.dating.backend.repository.LoginAttemptRepository;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest class LoginFailurePersistenceTest {
 @Autowired AuthService auth;@Autowired UserRepository users;@Autowired LoginAttemptRepository attempts;@Autowired PasswordEncoder passwords;
 @Test void failedLoginCountSurvivesOuterTransactionRollback(){String email="lockout-test@example.com";var user=users.save(User.builder().email(email).nickname("lockout-test").provider("LOCAL").status("ACTIVE").password(passwords.encode("Correct-password-123")).build());try{var r=new com.dating.backend.dto.AuthRequest();r.setEmail(email);r.setPassword("wrong-password");for(int i=0;i<5;i++)assertThrows(ResponseStatusException.class,()->auth.login(r));assertEquals(5,attempts.findByLoginId(email).orElseThrow().getFailureCount());assertEquals(429,assertThrows(ResponseStatusException.class,()->auth.login(r)).getStatusCode().value());}finally{attempts.findByLoginId(email).ifPresent(attempts::delete);users.deleteById(user.getId());}}
}
